namespace ghidra.feature.vt.gui.task;

using ghidra.feature.vt.api.db;
using ghidra.feature.vt.api.main;
using ghidra.framework.model;
using ghidra.program.model.listing;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.task;
using ghidra.util.task;



public class SetMatchTagTask : Task {

	protected List<VTMatch> matches;
	private VTSessionDB sessionDB;
	private VTMatchTag tag;

	public SetMatchTagTask(VTSession session, List<VTMatch> matches, VTMatchTag tag) : base("Set Match Tag", true, true, true, true)
    {
		this.tag = tag;

		if (!(session is VTSessionDB)) {
			throw new IllegalArgumentException(
				"Unexpected condition - VTSession is not a DB object!");
		}

		this.sessionDB = (VTSessionDB) session;
		this.matches = matches;
	}

	/* @Override */
	public void run(TaskMonitor monitor) {

		if (hasTransactionsOpen()) {
			return;
		}

		bool commit = true;
		int matchSetTransactionID = sessionDB.startTransaction(getTaskTitle());
		try {
			doWork(monitor);
		}
		catch (CancelledException e) {
			commit = false;
		}
		catch (Exception e) {
			commit = false;
			Msg.showError(this, null, "Unable to Set Match Tag",
				"An unexpected error occurred attempting to set match tag.", e);
		}
		finally {
			sessionDB.endTransaction(matchSetTransactionID, commit);
		}
	}

	private bool hasTransactionsOpen() {
		Program program = sessionDB.getDestinationProgram();
		TransactionInfo transaction = program.getCurrentTransactionInfo();
		if (transaction != null) {
			Msg.showWarn(this, null, "Unable to Set Match Tag",
				"The program \"" + program.getName() + "\"already has a transaction open: " +
					transaction.getDescription());
			return true;
		}

		TransactionInfo matchSetTransaction = sessionDB.getCurrentTransactionInfo();
		if (matchSetTransaction != null) {
			Msg.showWarn(this, null, "Unable to Set Match Tag",
				"Transaction already open for the Match Set Manager ");
			return true;
		}
		return false;
	}

	protected void doWork(TaskMonitor monitor)
    {
		monitor.initialize(matches.size());

		foreach (VTMatch match in matches) {
			monitor.checkCancelled();
			VTMatchTag currentTag = match.getTag();
			if (!currentTag.equals(tag)) {
				match.setTag(tag);
			}
			monitor.incrementProgress(1);
		}
	}
}
